// Generated by sema from Action function definitions.
use crate::{AssignmentOp, Context, ExprId, FlowId, OpId, PlaceId, ScopeId, SourceRange};

pub use crate::sema_gen::statements::{make_for, make_if_with_else, make_if_without_else, make_while};
pub fn append_statement(ctx: &mut Context, scope: ScopeId, operation: OpId) {
    ctx.scopes[scope.0].operations.push(operation);
}

pub fn call_statement(ctx: &mut Context, value: ExprId, source: SourceRange) -> OpId {
    ctx.add_operation(crate::model::Operation::Call(value), source)
}

pub fn check_assignment_target(
    ctx: &Context,
    place: PlaceId,
    operator: AssignmentOp,
) -> Result<(), &'static str> {
    agsem_runtime::check_assignment_target(ctx, place, operator, agsem_runtime::AssignmentPolicyErrors {
        invalid_target: "invalid assignment target",
        invalid_increment: "invalid increment operand",
        dependent: "dependent error",
        incompatible: "incompatible assignment types",
    })
}

pub fn condition_bool(ctx: &mut Context, value: ExprId) -> Result<ExprId, &'static str> {
    agsem_runtime::apply_condition_policy(ctx, value, agsem_runtime::ConditionPolicyErrors {
        dependent: "dependent error",
        incompatible: "condition is not convertible to bool",
    })
}

pub fn for_initialization(ctx: &mut Context, scope: ScopeId, source: SourceRange) -> OpId {
    let body = ctx.scopes[scope.0].operations.clone();
    ctx.add_operation(crate::model::Operation::Block { scope, body }, source)
}

pub fn function_return(
    ctx: &mut Context,
    value: Option<ExprId>,
    source: SourceRange,
) -> Result<OpId, &'static str> {
    agsem_runtime::apply_return_policy(
        ctx, value, source,
        agsem_runtime::ReturnPolicyErrors {
            missing_target: "return outside function",
            wrong_presence: "invalid return value",
            failed_conversion: "incompatible return type",
        },
    )
}

pub fn increment_value(
    ctx: &mut Context,
    place: PlaceId,
    increment: bool,
    source: SourceRange,
) -> Result<OpId, &'static str> {
    agsem_runtime::apply_increment_policy(ctx, place, increment, source, agsem_runtime::AssignmentPolicyErrors {
        invalid_target: "invalid assignment target",
        invalid_increment: "invalid increment operand",
        dependent: "dependent error",
        incompatible: "incompatible assignment types",
    })
}

pub fn merge_flow_snapshot(ctx: &mut Context, snapshot: FlowId) {
    ctx.current_flow = agsem_runtime::merge_flow_snapshot(&ctx.current_flow, &ctx.flow_snapshots, snapshot.0, |left, right| ctx.merge_flow(left, right));
}

pub fn recover_statement(
    ctx: &mut Context,
    snapshot: FlowId,
    message: &str,
    source: SourceRange,
) -> OpId {
    ctx.record_error(message, source);
    ctx.current_flow = agsem_runtime::restore_flow(&ctx.flow_snapshots, snapshot.0);
    ctx.add_operation(crate::model::Operation::Error, source)
}

pub fn restore_flow(ctx: &mut Context, snapshot: FlowId) {
    ctx.current_flow = agsem_runtime::restore_flow(&ctx.flow_snapshots, snapshot.0);
}

pub fn snapshot_flow(ctx: &mut Context) -> FlowId {
    FlowId(agsem_runtime::snapshot_flow(&ctx.current_flow, &mut ctx.flow_snapshots))
}

pub fn store_value(
    ctx: &mut Context,
    place: PlaceId,
    operator: AssignmentOp,
    value: ExprId,
    source: SourceRange,
) -> Result<OpId, &'static str> {
    agsem_runtime::apply_assignment_policy(ctx, place, operator, value, source, agsem_runtime::AssignmentPolicyErrors {
        invalid_target: "invalid assignment target",
        invalid_increment: "invalid increment operand",
        dependent: "dependent error",
        incompatible: "incompatible assignment types",
    })
}

impl agsem_runtime::ReturnPolicyContext for Context {
    type Expression = ExprId;
    type Type = crate::Type;
    type Operation = OpId;
    type Source = SourceRange;
    type Scope = crate::ScopeId;
    type Symbol = crate::SymbolId;

    fn return_value_is_poisoned(&self, value: ExprId) -> bool {
        self.poisoned_expression(value)
    }
    fn return_target_type(&self) -> Option<crate::Type> {
        self.active_function.map(|id| self.functions[id.0].result.clone())
    }
    fn return_type_is_void(&self, ty: &crate::Type) -> bool {
        *ty == crate::Type::Void
    }
    fn convert_return_value(&mut self, value: ExprId, ty: crate::Type) -> Result<ExprId, ()> {
        self.convert(value, ty).map_err(|_| ())
    }
    fn exit_scopes(&self) -> &[crate::ScopeId] { &[] }
    fn scope_symbols(&self, _scope: crate::ScopeId) -> &[crate::SymbolId] { &[] }
    fn destruct_on_return(&self, _symbol: crate::SymbolId) -> bool { false }
    fn commit_return(&mut self, value: Option<ExprId>, cleanup: Vec<crate::SymbolId>, source: SourceRange) -> OpId {
        self.current_flow.reachable = false;
        let _ = cleanup;
        self.add_operation(crate::model::Operation::Return(value), source)
    }
}

impl agsem_runtime::AssignmentPolicyContext for Context {
    type Place = PlaceId;
    type Assignment = AssignmentOp;
    type Expression = ExprId;
    type Type = crate::Type;
    type Source = SourceRange;
    type Operation = OpId;

    fn assignment_is_set(&self, operator: AssignmentOp) -> bool {
        operator == AssignmentOp::Set
    }
    fn assignment_target_type(&self, place: PlaceId) -> crate::Type {
        self.places[place.0].ty.clone()
    }
    fn assignment_target_is_array(&self, ty: &crate::Type) -> bool {
        matches!(ty, crate::Type::Array(_, _))
    }
    fn assignment_incrementable(&self, ty: &crate::Type) -> bool {
        matches!(ty, crate::Type::Int | crate::Type::Float | crate::Type::Char)
    }
    fn assignment_increment_operator(&self, increment: bool) -> AssignmentOp {
        if increment { AssignmentOp::Add } else { AssignmentOp::Subtract }
    }
    fn assignment_one(&mut self, source: SourceRange) -> Result<ExprId, &'static str> {
        self.integer_literal("1", source)
    }
    fn assignment_read_target(&self, place: PlaceId) -> Result<(), &'static str> {
        self.read(&self.current_flow, place)
    }
    fn assignment_value_is_poisoned(&self, value: ExprId) -> bool {
        self.poisoned_expression(value)
    }
    fn assignment_convert(&mut self, value: ExprId, target: crate::Type) -> Result<ExprId, ()> {
        self.convert(value, target).map_err(|_| ())
    }
    fn assignment_load(&mut self, place: PlaceId, target: crate::Type, source: SourceRange) -> ExprId {
        self.add_expression(crate::model::ExpressionKind::Load(place), target, source)
    }
    fn assignment_binary(&mut self, operation: AssignmentOp, left: ExprId, right: ExprId, source: SourceRange) -> Result<ExprId, ()> {
        let operator = match operation {
            AssignmentOp::Add => crate::model::Operator::Add,
            AssignmentOp::Subtract => crate::model::Operator::Subtract,
            AssignmentOp::Multiply => crate::model::Operator::Multiply,
            AssignmentOp::Divide => crate::model::Operator::Divide,
            AssignmentOp::Set => unreachable!(),
        };
        self.binary(operator, left, right, source).map_err(|_| ())
    }
    fn assignment_expression_type(&self, value: ExprId) -> crate::Type {
        self.expressions[value.0].ty.clone()
    }
    fn assignment_convert_result(&mut self, value: ExprId, target: crate::Type, source: SourceRange) -> Result<ExprId, ()> {
        let result_type = &self.expressions[value.0].ty;
        if !matches!(result_type, crate::Type::Int | crate::Type::Float | crate::Type::Char)
            || !matches!(target, crate::Type::Int | crate::Type::Float | crate::Type::Char) {
            return Err(());
        }
        Ok(self.add_expression(
            crate::model::ExpressionKind::Convert { value, target: target.clone() },
            target, source))
    }
    fn assignment_commit(&mut self, place: PlaceId, value: ExprId, compound: bool, source: SourceRange) -> OpId {
        let mut flow = self.current_flow.clone();
        self.mark_initialized(&mut flow, place);
        self.current_flow = flow;
        let operation = { let _ = compound; crate::model::Operation::Store { place, value } };
        self.add_operation(operation, source)
    }
}

impl agsem_runtime::ConditionPolicyContext for Context {
    type Expression = ExprId;
    type Type = crate::Type;
    type Source = crate::SourceRange;

    fn condition_is_poisoned(&self, value: ExprId) -> bool {
        self.poisoned_expression(value)
    }
    fn condition_type(&self, value: ExprId) -> crate::Type {
        self.expressions[value.0].ty.clone()
    }
    fn condition_is_bool(&self, ty: &crate::Type) -> bool {
        *ty == crate::Type::Bool
    }
    fn condition_convertible(&self, ty: &crate::Type) -> bool {
        matches!(ty, crate::Type::Int | crate::Type::Float | crate::Type::Char
            | crate::Type::CharPointer | crate::Type::NullPointer)
    }
    fn condition_source(&self, value: ExprId) -> crate::SourceRange {
        self.expressions[value.0].source
    }
    fn condition_convert_to_bool(&mut self, value: ExprId, source: crate::SourceRange) -> ExprId {
        self.add_expression(
            crate::model::ExpressionKind::Convert { value, target: crate::Type::Bool },
            crate::Type::Bool, source)
    }
}
